<template><section class="learning-questions"><h2>Learning enrollment</h2><p>Choose your program and tell us about the learner. This information helps us find support that fits.</p><div class="learning-fields"><label>Program<select :value="value.program" @change="set('program',$event.target.value)"><option value="tutoring">Tutoring</option><option value="academic-acceleration">Academic Acceleration</option><option value="bridge">Cognitive & Emotional Enrichment / Bridge</option></select></label><label>Current grade<select :value="value.grade" @change="set('grade',$event.target.value)"><option value="">Choose grade</option><option v-for="g in grades" :key="g">{{g}}</option></select></label><label>Subject<select :value="value.subject" @change="set('subject',$event.target.value)"><option value="">Choose a subject</option><option v-for="s in subjects" :key="s">{{s}}</option></select></label><label>Preferred learning format<select :value="value.format" @change="set('format',$event.target.value)"><option value="">Discuss with our team</option><option value="virtual">Virtual</option><option value="in-person">In person</option><option value="small-group">Small group</option></select></label></div><p v-if="value.program==='bridge'">The bridge program starts with weekly small-group skill development. Tutoring and counseling or therapy are coordinated through an individualized plan, based on needs, qualifications, and confirmed funding. Selecting this program does not guarantee insurance coverage.</p><label>Strengths and interests<textarea :value="value.strengths" @input="set('strengths',$event.target.value)" maxlength="3000" rows="2"/></label><label>Learning goals and current challenges<textarea :value="value.goals" @input="set('goals',$event.target.value)" maxlength="3000" rows="3"/></label><label>Current school supports (IEP, 504 plan, interventions, or other help)<textarea :value="value.schoolSupports" @input="set('schoolSupports',$event.target.value)" maxlength="3000" rows="2"/></label><template v-if="full||value.program==='bridge'"><label>What emotional, attention, or social challenges affect learning?<textarea :value="value.emotionalNeeds" @input="set('emotionalNeeds',$event.target.value)" maxlength="3000" rows="3"/></label><details><summary>Academic & emotional reflection (optional)</summary><p>These observations help start a conversation. There is no pass/fail score or diagnosis. Skip anything you cannot answer.</p><label>Who is answering?<select :value="value.reflectionVersion||'parent'" @change="changeReflection($event.target.value)"><option value="parent">Parent / guardian observations</option><option value="6-10">Student age 6–10</option><option value="11-13">Student age 11–13</option><option value="14-18">Student age 14–18</option></select></label><fieldset v-for="group in reflection" :key="group.category"><legend>{{group.category}}</legend><label v-for="item in group.items" :key="item.id" class="reflection-item"><span>{{item.text}}</span><select :value="value.reflectionAnswers?.[item.id]||''" @change="answer(item.id,$event.target.value)"><option value="">Skip / unsure</option><option value="1">1 — Rarely / Never</option><option value="2">2 — Sometimes</option><option value="3">3 — Often</option><option value="4">4 — Almost Always / Always</option></select></label></fieldset></details></template><label v-if="value.program==='bridge'">Funding or insurance to discuss<input :value="value.funding" @input="set('funding',$event.target.value)" maxlength="160" placeholder="Insurance plan, self-pay, or not sure"/></label><label>Package preference<select :value="value.packageId||''" @change="set('packageId',$event.target.value)"><option value="">Hourly support / help me choose</option><option v-for="p in packages" :key="p.id" :value="p.id">{{p.name}} — {{money(p.totalCents)}}</option></select></label><article v-for="p in packages.filter(p=>p.id===value.packageId)" :key="p.id"><h3>{{p.name}}</h3><ul><li v-for="(c,i) in p.components" :key="i">{{c.sessions}} × {{c.minutes}} minutes · {{c.service}} · {{c.format}} · {{c.educationLevel}} · {{money(c.totalCents)}}</li></ul><p>Package total: {{money(p.totalCents)}}. Your team confirms availability, fit, and payment arrangements before services begin.</p></article><p v-if="catalogError" role="status">Package information is temporarily unavailable. You can continue and discuss options with our team.</p></section></template>
<script setup>
import {computed,ref,watch} from 'vue';import api from '../../services/api';import reflections from '../../navigation/learningReflection.js';
const props=defineProps({modelValue:Object,program:{type:String,default:'tutoring'},agencySlug:{type:String,default:'nlu'},full:Boolean});const emit=defineEmits(['update:modelValue']);
const value=computed(()=>({version:1,program:props.program,format:props.program==='bridge'?'small-group':'',...props.modelValue}));
const grades=['Pre-K','K',...Array.from({length:12},(_,i)=>String(i+1)),'College'],subjects=['Math','Algebra','Geometry','Reading','Writing','Science','English','History','Study Skills','Homework Support','Test Prep','Other'];
const catalog=ref({packages:[]}),catalogError=ref(false),packages=computed(()=>catalog.value.packages.filter(p=>p.program===value.value.program)),reflection=computed(()=>reflections[value.value.reflectionVersion||'parent']);
function set(key,val){emit('update:modelValue',{...value.value,[key]:val,...(key==='program'?{packageId:'',format:val==='bridge'?'small-group':''}:{})});}
function changeReflection(version){emit('update:modelValue',{...value.value,reflectionVersion:version,reflectionAnswers:{}});}
function answer(id,val){set('reflectionAnswers',{...value.value.reflectionAnswers,[id]:val?Number(val):null});}
const money=c=>c==null?'Contact us for pricing':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(c/100);
watch(()=>props.agencySlug,async slug=>{if(!slug)return;try{catalog.value=(await api.get(`/public/agency-services/${encodeURIComponent(slug)}/learning-catalog`,{skipAuthRedirect:true,skipGlobalLoading:true})).data.catalog;}catch{catalogError.value=true;}},{immediate:true});
</script>
<style scoped>.learning-questions{padding:24px;border:1px solid #cee4e7;background:#f5fbfc;border-radius:12px;margin:20px 0;color:#153d53}.learning-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.learning-questions label{display:flex;flex-direction:column;gap:8px;margin:12px 0}.learning-questions select,.learning-questions textarea{font:inherit;padding:10px;border:1px solid #b4cdd3;border-radius:6px;max-width:100%;width:100%;box-sizing:border-box;background:white}.reflection-item{display:grid!important;grid-template-columns:minmax(0,1fr) minmax(180px,240px);align-items:center}.learning-questions fieldset{margin:18px 0;border:1px solid #c9dde0}.learning-questions summary{cursor:pointer;padding:12px 0}@media(max-width:600px){.learning-fields,.reflection-item{grid-template-columns:1fr}.learning-questions{padding:16px}}</style>
